        for attempt, attempts_remaining in enumerate(reversed(range(3))):
            try:
                with context.child("retrieving", f"retrieving {package}"):
                    await run_curtin_command(
                        self.app,
                        context,
                        "system-install",
                        "-t",
                        self.tpath(),
                        "--download-only",
                        "--",
                        package,
                        private_mounts=False,
                    )
            except subprocess.CalledProcessError:
                log.error(f"failed to download package {package}")
                if attempts_remaining > 0:
                    await asyncio.sleep(1 + attempt * 3)
                else:
                    raise
            else:
                break
        with context.child("unpacking", f"unpacking {package}"):
            await run_curtin_command(
                self.app,
                context,
                "system-install",
                "-t",
                self.tpath(),
                "--assume-downloaded",
                "--",
                package,
                private_mounts=False,
            )
        write_file(
            self.install_tree.p("etc/apt/sources.list"),
            f"deb [check-date=no] file:///cdrom {codename} main restricted\n",
