            self.dispose = None
            self.__frame = -1
            self._fp.seek(self.__rewind)
            self.disposal_method = 0
            if "comment" in self.info:
                del self.info["comment"]
        else:
            if self.tile and update_image:
                self.load()
        if frame != self.__frame + 1:
            raise ValueError(f"cannot seek to frame {frame}")
        self.fp = self._fp
        if self.__offset:
            self.fp.seek(self.__offset)
            while self.data():
                pass
            self.__offset = 0
        s = self.fp.read(1)
        if not s or s == b";":
            raise EOFError
        self.tile = []
        palette = None
        info = {}
        frame_transparency = None
        interlace = None
        frame_dispose_extent = None
        while True:
            if not s:
                s = self.fp.read(1)
            if not s or s == b";":
                break
            elif s == b"!":
                s = self.fp.read(1)
                block = self.data()
                if s[0] == 249:
                    flags = block[0]
                    if flags & 1:
                        frame_transparency = block[3]
