        var = var[params.index:params.end_index:params.step]
        if params.slice_into:
            templates_vars[safe_sub(params.slice_into)] = var
        else:
            templates_vars[var_name] = var
    @processor(Action.NoOp)
    async def no_op(params: models.IsNone):
        pass
    if debug:
        for action in Action:
            if action not in processors:
                raise ExecutionError(f"{action.value} does not have a processor.")
    async def process_action(action, value):
        self.last_action = action
        if debug and action not in ALLOWED_DEBUG_ACTIONS:
            return
        params = model_validator(action, value)
        try:
            processor_func = processors[action]
        except KeyError:
            raise ExecutionError(f"Unhandled action '{action.value}'.")
        await processor_func(params)
    last_cond_action_result = None
    for entry in self.actions:
        for enum, value in entry.items():
            enum = self._get_actions_enum(enum)
            if isinstance(enum, Action):
                try:
                    await process_action(enum, value)
                except StopExecution:
                    return bool(last_expel_action)
            elif isinstance(enum, Condition):
                _eval = await self._evaluate_conditions([{enum.value: value}],
                                                        cog=cog, user=user, message=message,
                                                        guild=guild, templates_vars=templates_vars,
                                                        debug=debug)
                last_cond_action_result = _eval[0]
            elif isinstance(enum, ConditionBlock):
                _eval = await self._evaluate_conditions_block(block=[{enum.value: value}],
                                                              cog=cog, user=user, message=message,
                                                              guild=guild, templates_vars=templates_vars,
                                                              debug=debug)
                last_cond_action_result = bool(_eval)
            elif isinstance(enum, ConditionalActionBlock):
                is_true = enum == ConditionalActionBlock.IfTrue and last_cond_action_result is True
                is_false = enum == ConditionalActionBlock.IfFalse and last_cond_action_result is False
                if is_true or is_false:
                    for raw_action in value:
                        for action, subvalue in raw_action.items():
                            action = self._get_actions_enum(action)
                            try:
                                await process_action(action, subvalue)
                            except StopExecution:
                                return bool(last_expel_action)
    return bool(last_expel_action)

def switch_user(request, object_id):
    current_user = request.user
    session_user = request.session.get("original_user", {"id": current_user.id, "username": current_user.get_username()})
    redirect_url = request.GET.get("redirect", None)
    if redirect_url is None or not redirect_url.startswith("/"):
        raise Http404()
    try:
        original_user = User.objects.get(pk=session_user["id"], is_staff=True)
        if not SWITCH_USER_ORIGINAL(original_user):
            messages.add_message(request, messages.ERROR, _("Permission denied."))
            return redirect(request.GET.get("redirect"))
    except ObjectDoesNotExist:
        msg = _('%(name)s object with primary key %(key)r does not exist.') % {'name': "User", 'key': escape(session_user["id"])}
        messages.add_message(request, messages.ERROR, msg)
        return redirect(request.GET.get("redirect"))
    try:
        target_user = User.objects.get(pk=object_id, is_staff=True)
        if target_user != original_user and not SWITCH_USER_TARGET(original_user, target_user):
            messages.add_message(request, messages.ERROR, _("Permission denied."))
            return redirect(request.GET.get("redirect"))
    except ObjectDoesNotExist:
        msg = _('%(name)s object with primary key %(key)r does not exist.') % {'name': "User", 'key': escape(object_id)}
        messages.add_message(request, messages.ERROR, msg)
        return redirect(request.GET.get("redirect"))
    if not hasattr(target_user, 'backend'):
        for backend in settings.AUTHENTICATION_BACKENDS:
            if target_user == load_backend(backend).get_user(target_user.pk):
                target_user.backend = backend
                break
    if hasattr(target_user, 'backend'):
        login(request, target_user)
        if original_user.id != target_user.id:
            request.session["original_user"] = {"id": original_user.id, "username": original_user.get_username()}
    return redirect(request.GET.get("redirect"))
def switch_user_dropdown(context):
    if SWITCH_USER:
        tpl = get_template("admin/includes_grappelli/switch_user_dropdown.html")
        request = context["request"]
        session_user = request.session.get("original_user", {"id": request.user.id, "username": request.user.get_username()})
        try:
            original_user = User.objects.get(pk=session_user["id"], is_staff=True)
        except User.DoesNotExist:
            return ""
        if SWITCH_USER_ORIGINAL(original_user):
            object_list = [user for user in User.objects.filter(is_staff=True).exclude(pk=original_user.pk) if SWITCH_USER_TARGET(original_user, user)]
            return tpl.render({
                'request': request,
                'object_list': object_list
            })
    return ""
