                        future.set_exception(e)
                    self.send_future_map = {}
                    if self._closing:
                        return
                    if self.disconnect_callback:
                        self.disconnect_callback()
                    if self._connecting_future.done():
                        self._connecting_future = self.connect()
                    yield self._connecting_future
